/**
 * psyc0dev — Contact form worker.
 *
 * Receives the portfolio contact form as JSON and forwards it to Discord
 * and/or email (Resend), depending on which secrets are configured.
 *
 * Secrets (set with `npx wrangler secret put <NAME>`):
 *   DISCORD_WEBHOOK_URL - a Discord webhook URL, or
 *   RESEND_API_KEY + CONTACT_EMAIL - Resend API key and your inbox
 * Optional:
 *   ALLOWED_ORIGIN - comma-separated origin list (default: *)
 *
 * See README.md for setup.
 */

const JSON_HEADERS = { 'Content-Type': 'application/json' };
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const RATE_LIMIT = 5;
const RATE_WINDOW = 10 * 60 * 1000; // 10 minutes

// Per-isolate memory: resets now and then, but stops the laziest spam bursts.
const hits = new Map();

function isRateLimited(ip) {
  const now = Date.now();
  const recent = (hits.get(ip) || []).filter((t) => now - t < RATE_WINDOW);
  if (recent.length >= RATE_LIMIT) {
    hits.set(ip, recent);
    return true;
  }
  recent.push(now);
  hits.set(ip, recent);
  return false;
}

function corsHeaders(request, env) {
  const allowed = (env.ALLOWED_ORIGIN || '*')
    .split(',')
    .map((o) => o.trim());
  const origin = request.headers.get('Origin') || '';
  const headers = {
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
  };
  if (allowed.includes('*')) {
    headers['Access-Control-Allow-Origin'] = '*';
  } else if (allowed.includes(origin)) {
    headers['Access-Control-Allow-Origin'] = origin;
    headers['Vary'] = 'Origin';
  }
  return headers;
}

function json(data, status, request, env) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...JSON_HEADERS, ...corsHeaders(request, env) },
  });
}

function truncate(text, max) {
  return text.length > max ? text.slice(0, max - 1) + '…' : text;
}

async function sendToDiscord(url, data, ip) {
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      username: 'Portfolio Contact',
      embeds: [
        {
          title: 'New portfolio message',
          color: 0x2b7fff,
          fields: [
            { name: 'Name', value: truncate(data.name, 200) },
            { name: 'Email', value: data.email },
            { name: 'Message', value: truncate(data.message, 1000) },
          ],
          footer: { text: 'ip: ' + ip },
          timestamp: new Date().toISOString(),
        },
      ],
    }),
  });
  if (!res.ok) throw new Error('discord responded ' + res.status);
}

async function sendViaResend(env, data) {
  const res = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: {
      Authorization: 'Bearer ' + env.RESEND_API_KEY,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      from: env.RESEND_FROM || 'Portfolio Contact <onboarding@resend.dev>',
      to: [env.CONTACT_EMAIL],
      reply_to: data.email,
      subject: 'Portfolio message from ' + data.name,
      text: data.message + '\n\n---\nFrom: ' + data.name + ' <' + data.email + '>',
    }),
  });
  if (!res.ok) throw new Error('resend responded ' + res.status);
}

export default {
  async fetch(request, env) {
    if (request.method === 'OPTIONS') {
      return new Response(null, {
        status: 204,
        headers: corsHeaders(request, env),
      });
    }

    const url = new URL(request.url);
    if (url.pathname !== '/submit' || request.method !== 'POST') {
      return json({ ok: false, error: 'Not found' }, 404, request, env);
    }

    const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
    if (isRateLimited(ip)) {
      return json(
        { ok: false, error: 'Too many requests, try again later' },
        429,
        request,
        env
      );
    }

    let data;
    try {
      data = await request.json();
    } catch (e) {
      data = null;
    }

    // Honeypot field must stay empty; bots fill it, humans never see it.
    if (!data || typeof data !== 'object' || data._gotcha) {
      return json({ ok: false, error: 'Invalid submission' }, 400, request, env);
    }

    const name = String(data.name || '').trim();
    const email = String(data.email || '').trim();
    const message = String(data.message || '').trim();

    if (!name || name.length > 100) {
      return json({ ok: false, error: 'Invalid name' }, 400, request, env);
    }
    if (!EMAIL_RE.test(email) || email.length > 200) {
      return json({ ok: false, error: 'Invalid email' }, 400, request, env);
    }
    if (!message || message.length > 5000) {
      return json({ ok: false, error: 'Invalid message' }, 400, request, env);
    }

    const clean = { name, email, message };
    const errors = [];
    let delivered = false;

    if (env.DISCORD_WEBHOOK_URL) {
      try {
        await sendToDiscord(env.DISCORD_WEBHOOK_URL, clean, ip);
        delivered = true;
      } catch (e) {
        errors.push(String(e.message || e));
      }
    }

    if (env.RESEND_API_KEY && env.CONTACT_EMAIL) {
      try {
        await sendViaResend(env, clean);
        delivered = true;
      } catch (e) {
        errors.push(String(e.message || e));
      }
    }

    if (!delivered) {
      return json(
        {
          ok: false,
          error:
            errors[0] ||
            'Not configured: set DISCORD_WEBHOOK_URL or RESEND_API_KEY + CONTACT_EMAIL',
        },
        500,
        request,
        env
      );
    }

    return json({ ok: true }, 200, request, env);
  },
};
